def main():
    assert len(DATA) == 20, f"DATA count {len(DATA)} != 20"
    seen = set()
    for e in DATA:
        assert set(e.keys()) == {"case_id","prediction_text","basis","confidence"}, e["case_id"]
        assert e["case_id"] in IDS and e["case_id"] not in seen, e["case_id"]
        seen.add(e["case_id"])
        assert isinstance(e["confidence"], float) and 0.0 <= e["confidence"] <= 1.0
        assert e["prediction_text"].strip() and e["basis"].strip()
    assert seen == set(IDS), f"coverage mismatch: {set(IDS)-seen}"
    os.makedirs(OUT, exist_ok=True)
    for e in DATA:
        rec = {"case_id": e["case_id"], "prediction_text": e["prediction_text"],
               "basis": e["basis"], "confidence": e["confidence"], "trigger": dict(TRIG)}
        path = os.path.join(OUT, e["case_id"] + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
    # per-file self-verify: exact open each of the 20, no directory listing
    for cid in IDS:
        with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
            r = json.load(f)
        assert list(r.keys()) == ["case_id","prediction_text","basis","confidence","trigger"], cid
        assert r["case_id"] == cid
        assert r["trigger"] == TRIG, cid
    print(f"OK wrote+verified {len(DATA)} files")

if __name__ == "__main__":
    main()
